#include <cstdio>
#include <algorithm>

using namespace std;

int main() {
    int x;

    while (scanf("%d", &x), x) {
        if (x % 1111 == 0) {
            puts("NA");
        } else {
            int ans;
            for (ans = 0; x != 6174; ++ans) {
                int a = 0, b = 0;
                // Using a single integer to extract digits
                int temp = x;
                for (int i = 0; i < 4; ++i) {
                    int digit = temp % 10;
                    temp /= 10;
                    a = a * 10 + digit; // create number from digits
                }
                // Sort digits by creating an array from the number
                int s[4];
                for (int i = 0; i < 4; ++i) {
                    s[i] = a % 10; // extract digits from constructed number
                    a /= 10;
                }
                sort(s, s + 4);
                a = 0; b = 0;
                for (int i = 0; i < 4; ++i) {
                    a = a * 10 + s[i]; // create smallest number
                    b = b * 10 + s[3 - i]; // create largest number
                }
                x = b - a;
            }
            printf("%d\n", ans);
        }
    }
}

